/** Look up a team by its ID. */
export function getTeamById(id: string): Team | undefined {
  return TEAMS.find(t => t.id === id);
}

/** Filter teams by league, with optional search query. */
export function filterTeams(league: SportKey | 'all', query: string): Team[] {
  return TEAMS.filter(t => {
    const matchesLeague = league === 'all' || t.league === league;
    const matchesQuery = !query || [t.name, t.shortName, t.city, t.abbreviation]
      .some(s => s.toLowerCase().includes(query.toLowerCase()));
    return matchesLeague && matchesQuery;
  });
}
